// 新Common回执片先在独立typed门核，尚未注册的模块不能借此宣称旧银行通过。
#define main naval_source_cases
#include "naval_world_test.cpp"
#undef main
#include "resident/domains/military/naval_command_codec.hpp"
// 严格入口与重哈希缓存来源逐项拒绝，往返保完整字段次序。
int main(){try{WorldFixture f;f.common.state().next_instance_id=4;auto command=take(parse_boundary_json(R"({"kind":"naval_form","request_key":"first","army_id":"army:1","assignments":[{"vessel_id":"ship0","unit_id":"unit0","passenger_ids":[],"prisoner_ids":[],"extra_inventory_ids":["army_store"]},{"vessel_id":"ship1","unit_id":"unit1","passenger_ids":[],"prisoner_ids":[],"extra_inventory_ids":[]}]})"));auto parsed=take(naval_command_codec::decode_command(command));auto r=take(apply_naval_command(f.common,f.military,f.mc,f.access,f.state,f.catalog,"captain0",parsed));check(naval_command_codec::validate_cached_receipt(f.state,r,"captain0").ok,"real command receipt resolves to exact fleet origin");auto value=naval_command_codec::encode_receipt(r);auto decoded=take(naval_command_codec::decode_receipt(value));CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);check(naval_command_codec::visit_receipt(writer,decoded).ok&&writer.finish().ok,"finite typed command receipt writes");NavalCommandReceipt restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));check(naval_command_codec::visit_receipt(reader,restored).ok&&reader.finish().ok,"finite typed receipt reads");check(take(render_boundary_json(value))==take(render_boundary_json(naval_command_codec::encode_receipt(restored))),"same ordered receipt survives typed cold boundary");
 auto bad=r;bad.tick++;check(!naval_command_codec::validate_cached_receipt(f.state,bad,"captain0").ok,"forged receipt tick rejected despite valid typed fields");bad=r;bad.actor_id="captain1";check(!naval_command_codec::validate_cached_receipt(f.state,bad,"captain1").ok,"another actor cannot borrow original receipt");bad=r;bad.request_key="changed";check(!naval_command_codec::validate_cached_receipt(f.state,bad,"captain0").ok,"receipt key remains bound to original intent");auto forged=value;forged.as<BoundaryValue::Dict>()->emplace_back("money",BoundaryValue{Integer{1}});check(!naval_command_codec::decode_receipt(forged).ok,"receipt cannot smuggle a transfer field");auto hidden=command;hidden.as<BoundaryValue::Dict>()->emplace_back("repair",BoundaryValue{true});check(!naval_command_codec::decode_command(hidden).ok,"zero-time form cannot imply repair");check(!naval_command_codec::decode_command(take(parse_boundary_json(R"({"kind":"naval_sink","request_key":"x"})"))).ok,"unsupported sinking command rejects explicitly");std::cout<<"NAVAL_COMMAND_CODEC_CHECKS="<<checks<<" FAILURES=0 SCOPE=COMPONENT\n";return 0;}catch(const std::exception& e){std::cerr<<"NAVAL_COMMAND_CODEC_FAIL checks="<<checks<<" "<<e.what()<<'\n';return 1;}}
